function sleep(ms: number): Promise<void> {
  return new Promise<void>((r) => setTimeout(r, ms));
}
async function worker(n: string, ms: number): Promise<string> {
  await sleep(ms);
  return n;
}
async function fail(ms: number): Promise<string> {
  await sleep(ms);
  throw new Error("bad");
}
async function run(): Promise<void> {
  worker("slow", 400);
  const t = Date.now();
  const r = await Promise.allSettled([worker("a", 30), worker("b", 5), fail(10)]);
  console.log(Date.now() - t < 200);
  console.log(r.map((x) => x.status));
  console.log(r[0], r[1]);
  console.log((r[2] as PromiseRejectedResult).reason.message);
}
function main(): void {
  run();
}
